import{z as o,x as s,o as r,c as d,q as t,j as i,D as B,d as e,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"组合过拟合 CPCV","description":"","frontmatter":{"title":"组合过拟合 CPCV","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cpcv.md","filePath":"quant/cpcv.md","lastUpdated":1791413859000}'),C={name:"quant/cpcv.md"};function p(P,a,h,m,D,c){const A=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="组合过拟合-cpcv" tabindex="-1">组合过拟合 CPCV <a class="header-anchor" href="#组合过拟合-cpcv" aria-label="Permalink to &quot;组合过拟合 CPCV&quot;">​</a></h1><div class="epigraph"><p>单条样本外路径太容易被选中；组合对称地生成许多条训练–检验划分，才能估计「样本内冠军在样本外仍高于中位数」这一事件的概率。</p><footer>—— Bailey, Borwein, López de Prado and Zhu, The Probability of Backtest Overfitting, Journal of Computational Finance, 2017；López de Prado, AFML, Chapter 12</footer></div><p><a href="/quant/deflated-sharpe">Deflated Sharpe</a>把尝试次数折进夏普阈值，路径方法留到本课。滚动检验给出一条沿时间拼接的样本外曲线，信息有限：窗口个数通常是十几，而且相邻窗口共享状态。Bailey、Borwein、López de Prado 与 Zhu（2017）问的是另一个量：在你搜索过的策略集合里，把样本内最优者拿到样本外，它的表现低于中位数的概率有多大——回测过拟合概率（Probability of Backtest Overfitting, PBO）。估计 PBO 需要许多条对称的训练–检验划分，而不是一条幸运的切分。组合对称交叉验证（CSCV）以及 López de Prado 在 <em>Advances in Financial Machine Learning</em> 第 12 章写的组合清洗交叉验证（Combinatorial Purged Cross-Validation, CPCV），就是为了生成这些路径。它们是实验设计，不是又一种优化器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设候选策略有 \\(M\\) 个，历史长度 \\(T\\)。样本内挑出夏普最高的 \\(m^\\star\\)，再看它在某段样本外的夏普。若只有一次切分，\\(m^\\star\\) 的样本外好坏高度依赖切点：末端若正好是该策略擅长的体制，你会相信发现；末端若不擅长，你会改切点。PBO 把「样本内最优在样本外相对整个集合的表现差于中位」定义为过拟合事件。技能真实且选择温和时，PBO 应明显低于 \\(1/2\\)；纯噪声搜索时，PBO 接近 \\(1/2\\) 或更高——冠军在样本外没有优势。<span class="marginnote">术语翻译：PBO（回测过拟合概率）回答的是「你的样本内冠军，有多大可能只是这一段历史的幸运儿」。它把冠军放到样本外与整个候选集合比相对排名：若一半以上的划分里它连中位数都不到，这个「冠军」更像是被噪声抬上去的。</span></p><p>\\(K\\) 折交叉验证路径太少（只有 \\(K\\) 条），且金融里有<a href="/quant/cv-leakage-finance">标签泄漏</a>。普通 walk-forward 路径更少。要估计一个概率，需要组合：把 \\(T\\) 分成 \\(S\\) 组，在 \\(\\binom{S}{S/2}\\) 种「一半训练、一半检验」的划分上重复「样本内选冠军、样本外记相对排名」。这就是 CSCV 的骨架。CPCV 在同一骨架上加上清洗与禁运，使每一条路径的训练标签不偷看检验期。</p><h3 id="为什么对称划分" tabindex="-1">为什么对称划分 <a class="header-anchor" href="#为什么对称划分" aria-label="Permalink to &quot;为什么对称划分&quot;">​</a></h3><p>若总是「前半训练、后半检验」，所有路径共享同一个时间箭头，估计的是某种特定的非平稳，而不是选择偏差本身。组合对称让每一段历史都有机会当训练、也有机会当检验，从而把「这段日子特别好」平均掉，留下「挑选冠军」这一操作带来的偏差。代价是部分路径在时间上是交错的，不再模拟真实的部署顺序；PBO 度量的是过拟合，不是可部署性。可部署性仍要靠<a href="/quant/walk-forward">滚动</a>那一条遵守因果的路径。</p><p><span class="marginnote">PBO \\(=0.2\\) 不是许可。它只说明在你声明的候选集合与划分方案下，冠军并不系统性地在样本外掉到中位以下。候选集合若事先用全样本筛过一遍，PBO 会假低：真正的搜索空间比送进 CPCV 的 \\(M\\) 更大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CSCV（Bailey 等，2017）。将观测均分为 \\(S\\) 个连续块（\\(S\\) 为偶数）。每一个组合 \\(c\\) 取其中 \\(S/2\\) 块为训练、互补块为检验。在训练块上对 \\(M\\) 个策略评分，记下最优者 \\(m^\\star_c\\)，再看 \\(m^\\star_c\\) 在检验块上相对 \\(M\\) 个策略的相对排名。若一半以上的组合里 \\(m^\\star_c\\) 的样本外表现低于中位数，则 \\(\\widehat{\\mathrm{PBO}}\\) 高。同时可画样本内绩效与样本外绩效的散点：过拟合表现为明显的负斜率——样本内越好，样本外越差。<span class="marginnote">直觉类比：把 \\(M\\) 个策略的样本内与样本外成绩画成散点。健康情形像一场真实的考试——平时分与正式考分正相关；过拟合像抄了近道——平时分越高，正式考砸得越狠，散点于是向右下倾斜。</span></p><p>CPCV（AFML 第 12 章）。测试集不再固定为「一半块」，而是从 \\(N\\) 个组里组合出 \\(k\\) 个测试组，生成 \\(\\binom{N}{k}\\) 条路径；每条路径上对训练样本做 purge 与 embargo，避免标签重叠。每个观测会出现在多条测试路径里，于是得到该观测上的一簇样本外预测或收益，而不只是单次切分的一个点。这比 \\(K\\) 折更充分地使用数据，也比单次 walk-forward 更能看到评估的不确定性。</p><h3 id="报告什么" tabindex="-1">报告什么 <a class="header-anchor" href="#报告什么" aria-label="Permalink to &quot;报告什么&quot;">​</a></h3><p>最低报告应包括：候选集合如何构造（是否含已被全样本淘汰的兄弟）、\\(S\\) 或 \\((N,k)\\)、清洗长度、\\(\\widehat{\\mathrm{PBO}}\\)、IS–OOS 散点、以及各条路径样本外夏普的分布。López de Prado 建议把回测看成对无偏评估器的输入，而不是看成一张权益曲线。CPCV 的输出是分布；只摘分布的上分位，等于把组合验证又变成一次选择。若还要报一个点估计，应预先声明是路径中位数还是遵守时间顺序的那条滚动路径，不能是路径最大值。</p><p><span class="marginnote">候选之间高度相关时，\\(M\\) 很大但有效试验很少，PBO 可能看起来很好——大家样本外一起好或一起坏，冠军相对中位的优势稳定，却只是同一个赌注。应先对策略收益做相关聚类，按有效独立个数读 PBO，并与 <a href="/quant/deflated-sharpe">Deflated Sharpe</a> 的有效 \\(N\\) 交叉核对。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选择偏差的几何图像是：样本内绩效把噪声抬进冠军，样本外噪声独立（在无泄漏、无重叠标签时），于是冠军的样本外条件期望低于它的样本内，甚至低于集合的无条件中位。CSCV 用对称划分逼近这种条件期望。若泄漏存在，训练与检验共享噪声，PBO 被压低，过拟合被评估器藏起来——所以 CPCV 必须先 purge。这与 White Reality Check 的精神一致：承认你看了许多规则；差别在于 CPCV/PBO 给出的是路径上的相对排名概率，Reality Check 给出的是最大统计量相对基准的 \\(p\\) 值。</p><p>路径条数随组合数指数增长，这是有意的。\\(K\\) 折的 \\(K\\) 条路径估计不出「冠军掉到中位以下」这种尾部事件。<span class="marginnote">数字实例：\\(S=16\\) 块时「一半训练、一半检验」的组合有 \\(\\binom{16}{8}=12870\\) 种，足以把「冠军掉到中位以下」的频率估稳；\\(K\\) 折只有 5 到 10 条路径，这种尾部事件的频率根本估不准——这就是为什么必须组合。</span>组合验证用的是同一段历史的不同切法，不是新的历史：它不能创造信息，只能把已有信息里被切分选择所掩盖的变异性展示出来。因此 CPCV 不能拯救一个只有三年数据的高换手策略；三年数据的组合路径高度依赖同一段噪声实现。</p><h3 id="与滚动、dsr-如何一起用" tabindex="-1">与滚动、DSR 如何一起用 <a class="header-anchor" href="#与滚动、dsr-如何一起用" aria-label="Permalink to &quot;与滚动、DSR 如何一起用&quot;">​</a></h3><p>一个完整的实验设计可以是：用 CPCV 估计搜索是否过拟合，用 DSR 给最终候选的夏普放气，用嵌套滚动给出一条可叙述的因果样本外曲线，用成本与容量决定能否交易。四者回答不同问题。只用滚动，你不知道若切分不同会怎样；只用 DSR，你不知道相对排名；只用 PBO，你没有一张可审计的「若从某年做到某年」的权益曲线。López de Prado 把 CPCV 放在回测架构的中心，正是因为业界最常犯的错是把一条路径的夏普当成总体参数。</p>',20)),(r(),i(l,null,{default:B(()=>[n(A,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E6%90%9C%E7%B4%A2%E6%98%AF%E5%90%A6%E8%BF%87%E6%8B%9F%E5%90%88%3F%22%5D%20--%3E%20A1%5B%22CPCV%20%2F%20PBO%22%5D%0A%20%20Q2%5B%22%E5%A4%8F%E6%99%AE%E6%89%A3%E6%8E%89%E5%B0%9D%E8%AF%95%E6%AC%A1%E6%95%B0%E8%BF%98%E5%89%A9%E5%A4%9A%E5%B0%91%3F%22%5D%20--%3E%20A2%5B%22Deflated%20Sharpe%22%5D%0A%20%20Q3%5B%22%E6%8C%89%E6%97%B6%E9%97%B4%E9%A1%BA%E5%BA%8F%E8%83%BD%E5%90%A6%E9%83%A8%E7%BD%B2%3F%22%5D%20--%3E%20A3%5B%22%E5%B5%8C%E5%A5%97%E5%9B%A0%E6%9E%9C%E6%BB%9A%E5%8A%A8%22%5D%0A%20%20Q4%5B%22%E6%89%A3%E8%B4%B9%E4%B8%8E%E6%8E%A7%E8%A7%84%E6%A8%A1%E5%90%8E%E8%83%BD%E5%90%A6%E4%BA%A4%E6%98%93%3F%22%5D%20--%3E%20A4%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E5%AE%B9%E9%87%8F%E5%88%86%E6%9E%90%22%5D%0A%20%20A1%20--%3E%20GATE%7B%22%E5%9B%9B%E5%85%B3%E9%83%BD%E8%BF%87%3F%22%7D%0A%20%20A2%20--%3E%20GATE%0A%20%20A3%20--%3E%20GATE%0A%20%20A4%20--%3E%20GATE%0A%20%20GATE%20--%20%22%E6%98%AF%22%20--%3E%20GO%5B%22%E8%BF%9B%E5%85%A5%E6%A8%A1%E6%8B%9F%E7%9B%98%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"边界",tabindex:"-1"},[e("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("组合路径不是交易模拟。交错的训练/检验块无法对应真实的下单顺序，也不能直接用来估"),E("a",{href:"/quant/cost-sensitivity"},"冲击"),e("。PBO 低且 DSR 高的策略，仍可能在因果滚动上因非平稳而失败。反过来，PBO 接近 \\(1/2\\) 时，几乎不应进入模拟账户：你还没有证据表明搜索产生了可迁移的优势。")],-1)),a[5]||(a[5]=E("p",null,"计算上 \\(\\binom{N}{k}\\) 可以很大，需要对策略向量化评分，而不是对每条路径重跑订单级回测。若评分函数本身有泄漏（全样本标准化），CPCV 只是把泄漏复制到每一条路径。候选集合必须冻结：看到 PBO 偏高就删掉一些差的候选再算一次，PBO 会下降，这是对评估器动手。诚实的做法是扩大报告：给出搜索日志上的 PBO，而不是给出清洗后集合上的 PBO。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"Bailey 等人也讨论过拟合的「第二类」错误：真技能被保守评估杀掉。PBO 不是越小越好的目标函数；把它当优化目标去调 \\(S\\)、调清洗、调 \\(M\\)，会得到好看的 PBO 和同样过拟合的系统。")],-1)),(r(),i(l,null,{default:B(()=>[n(A,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%86%BB%E7%BB%93%E7%9A%84%20M%20%E4%B8%AA%E5%80%99%E9%80%89%22%5D%20--%3E%20BLK%5B%22%E5%88%86%E6%88%90%20N%20%E4%B8%AA%E6%97%B6%E9%97%B4%E5%9D%97%22%5D%0A%20%20BLK%20--%3E%20COMB%5B%22%E7%BB%84%E5%90%88%E5%87%BA%E5%A4%9A%E6%9D%A1%E8%AE%AD%E7%BB%83%2F%E6%A3%80%E9%AA%8C%E8%B7%AF%E5%BE%84%22%5D%0A%20%20COMB%20--%3E%20PURGE%5B%22%E6%AF%8F%E6%9D%A1%E8%B7%AF%E5%BE%84%EF%BC%9A%E6%B8%85%E6%B4%97%E4%B8%8E%E7%A6%81%E8%BF%90%22%5D%0A%20%20PURGE%20--%3E%20IS%5B%22%E8%AE%AD%E7%BB%83%E5%9D%97%E4%B8%8A%E9%80%89%E5%87%BA%E5%86%A0%E5%86%9B%22%5D%0A%20%20IS%20--%3E%20OOS%5B%22%E6%A3%80%E9%AA%8C%E5%9D%97%E4%B8%8A%E8%AE%B0%E5%BD%95%E7%9B%B8%E5%AF%B9%E6%8E%92%E5%90%8D%E4%B8%8E%E7%BB%A9%E6%95%88%22%5D%0A%20%20OOS%20--%3E%20PBO%5B%22PBO%EF%BC%9A%E5%86%A0%E5%86%9B%E6%A0%B7%E6%9C%AC%E5%A4%96%E4%BD%8E%E4%BA%8E%E4%B8%AD%E4%BD%8D%E7%9A%84%E6%AF%94%E4%BE%8B%22%5D%0A%20%20OOS%20--%3E%20DIST%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E7%9A%84%20OOS%20%E7%BB%A9%E6%95%88%E5%88%86%E5%B8%83%22%5D%0A%20%20PBO%20--%3E%20DEC%7B%22PBO%20%E6%98%AF%E5%90%A6%E8%BF%9C%E4%BD%8E%E4%BA%8E%201%2F2%3F%22%7D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20STOP%5B%22%E6%90%9C%E7%B4%A2%E8%BF%87%E6%8B%9F%E5%90%88%EF%BC%9B%E5%81%9C%E6%AD%A2%E9%83%A8%E7%BD%B2%22%5D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20NEXT%5B%22%E5%86%8D%E7%9C%8B%20DSR%E3%80%81%E5%9B%A0%E6%9E%9C%E6%BB%9A%E5%8A%A8%E3%80%81%E6%88%90%E6%9C%AC%E5%AE%B9%E9%87%8F%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPCV/CSCV 用组合划分生成许多条样本外路径，用来估计回测过拟合概率，而不是用来再挑一个更漂亮的切分。</li><li>PBO 高意味着样本内冠军在样本外没有稳定的相对优势；路径中位数与 IS–OOS 散点应一起报告。</li><li>金融标签必须在每条路径上 purge/embargo，否则 PBO 被泄漏压低。</li><li>组合路径度量选择偏差，不替代遵守时间顺序的滚动模拟，也不替代成本。</li><li>候选集合与划分方案必须冻结；在 PBO 上再优化是第二层过拟合。</li><li>出处：Bailey, Borwein, López de Prado and Zhu, <em>Journal of Computational Finance</em>, 2017；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018，第 7、12 章；White, <em>Econometrica</em>, 2000。</li></ul>',2))])}const f=o(C,[["render",p]]);export{O as __pageData,f as default};
